		sections={
			{id=34313,title="Overview",body="Scourgelord Tyrannus opens his assault with |cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r while his dragon, Rimefang, attacks from the air with |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r. While building his power, Scourgelord Tyrannus unleashes |cFF2959D3|Hspell:1263756|h[Death's Grasp]|h|r and |cFF2959D3|Hspell:1262582|h[Scourgelord's Brand]|h|r.\n\nUpon reaching 100 energy, he raises undead minions with |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r."},
			{id=35183,title="Damage Dealers",body="$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons a swarm of minions.\n$bullet;Rimefang's |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r freezes any |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r it impacts.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263756|h[Death's Grasp]|h|r and Rimefang's |cFF2959D3|Hspell:1276948|h[Ice Barrage]|h|r inflict significant damage at targeted locations.",difficultyIDs={1,2,19,24,150,205,216,236}},
			{id=34314,title="Damage Dealers",body="$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons a swarm of minions.\n$bullet;Rimefang's |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r freezes any |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r or |cFF2959D3|Hspell:1276391|h[Infused Bone Piles]|h|r it impacts.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r empowers some |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r.",difficultyIDs={23}},
			{id=35184,title="Healer",body="$bullet;|cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r, |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r, and |cFF2959D3|Hspell:1262739|h[Frost Spit]|h|r inflict significant damage to players.\n$bullet;Rimefang's |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r freezes any |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r it impacts.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons minions that inflict significant damage to players.",difficultyIDs={1,2,19,24,150,205,216,236}},
			{id=34315,title="Healer",body="$bullet;|cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r, |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r, and |cFF2959D3|Hspell:1262739|h[Frost Spit]|h|r inflict significant damage to players.\n$bullet;Rimefang's |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r freezes any |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r or |cFF2959D3|Hspell:1276391|h[Infused Bone Piles]|h|r it impacts.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons minions that inflict significant damage to players.",difficultyIDs={23}},
