		sections={
			{id=7582,title="Phase 1: The Black Knight"},
			{id=7583,title="Death's Respite",body="The Black Knight stuns a player for $67745d, inflicting Shadow damage and knocking them back."},
			{id=7584,title="Icy Touch",body="The Black Knight grips a player in his icy hands, inflicting Frost damage and afflicting them with Frost Fever."},
			{id=7585,title="Frost Fever",body="The Black Knight's Icy Touch afflicts players with a Frost Fever, inflicting Frost damage every $67719t1 sec. and reducing melee and ranged attack speed by $67719s2% for $67719d."},
			{id=7586,title="Plague Strike",body="The Black Knight viciously strikes a player, inflicting Physical damage and plaguing them with Blood Plague."},
			{id=7587,title="Blood Plague",body="The Black Knight's Plague Strike afflicts players with Blood Plague, inflicing Shadow damage every $67722t1 sec. for $67722d."},
			{id=7595,title="Obliterate",body="The Black Knight brutaly strikes a player, inflicting Physical damage that is increased by the number of diseases the target is afflicted with. Obliterate removes all diseases from the target when they are struck."},
			{id=7588,title="Raise Argent Herald",body="The Black Knight raises the argent herald as a mindless ghoul."},
			{id=7589,title="Risen Argent Herald"},
			{id=7590,title="Claw",body="The Risen Argent Herald claws a player, inflicting Physical damage."},
			{id=7591,title="Leap",body="The Risen Argent Herald leaps behind a random player, inflicting Physical damage."},
			{id=7592,title="Ghoul Explode",body="When the Risen Argent Herald reaches 30% health remaining or when The Black Knight is killed, he explodes, inflicting Shadow damage to all players within $67729A1 yards."},
			{id=7593,title="Phase 2: The Undead",body="When the Black Knight is killed, he is risen as a skeleton to continue his fight. He retains Plague Strike, Icy Touch and Obliterate from his living form and gains new abilities."},
			{id=7596,title="Desecration",body="The Black Knight desecrates the ground at a player's location. The desecration inflicts Shadow damage and slows all players within it every second. The ground remains desecrated for $67779d."},
			{id=7597,title="Army of the Dead",body="The Black Knight summons an entire legion of Ghouls to fight for him."},
			{id=7598,title="Ghoul Explode",body="The Black Knight causes one of his ghouls to explode, inflicting Shadow damage to all players within $67729A1 yards."},
			{id=7594,title="Phase 3: The Afterlife",body="When the Black Knight's skeleton form is destroyed, he is risen as a ghost for his final stand. As a ghost he loses all of his abilities from his previous forms."},
			{id=7599,title="Death's Bite",body="The Black Knight inflicts Shadowfrost damage to all players and increases their magic damage taken by $67808s3% for $67808d. This effect stacks up to $67808U times."},
			{id=7600,title="Marked For Death",body="The Black Knight marks a player for death, increasing their magic damage taken by $67823s1% for $67823d."},
		},
