	[639]={
		encounterID=639,
		instanceID=285,
		order=2,
		name="Skarvald & Dalronn",
		lore="It's a vrykul tradition to make unlikely partners work together. Some say it's to allow divergent abilities to complement each other; others say it's for the amusement of King Ymiron. Regardless, Skarvald and Dalronn are a perfect example of this custom. Between a vrykul's brawn and a human's necromantic arts, they will punish those who meddle with the Scourge.",
