			{id=7662,title="Ritual of the Sword",body="Svala Sorrowgrave summons a random player to her altar and begins to sacrifice them. While being sacrificed, three Ritual Channelers cast Paralyze on the player, stunning them until the channelers are killed."},
			{id=7665,title="Ritual Strike",body="After 25 seconds, Svala's sword falls to the altar and inflits Shadow damage to all players within $48277A1 yards. In addition, any player hit by the sword becomes corrupted, causing Shadow damage every second for $48277d."},
