	[642]={
		encounterID=642,
		instanceID=286,
		order=2,
		name="Gortok Palehoof",
		lore="The vrykul keep many trophies at Utgarde Keep, and Gortok is among the most impressive. King Ymiron displays the frozen magnataur's cruel countenance as a reminder that even the most savage beasts are mere decorations for vrykul halls. This living statue will sow destruction if liberated, unleashing his wrath indiscriminately.",
