		sections={
			{id=7669,title="Stasis Generator",body="Using the Stasis Generator causes two random hunting trophies to become active and attack players.\n\nOnce the hunting trophies are defeated, Gortok Palehoof becomes active.$[!2\n\nIn Heroic Difficulty, all four hunting trophies must be defeated before Gortok Plaehoof will activate.$]"},
			{id=7670,title="Stage 1: The Hunting Trophies"},
			{id=7671,title="Ferocious Rhino"},
			{id=7676,title="Grievous Wound",body="The Ferocious Rhino charges a random player, inflicting Physical damage and additional Physical damage every second. The Grievous Wound effect lasts for $48105d, or until the player is healed to full health."},
			{id=7677,title="Gore",body="The Ferocious Rhino gores a player, inflicting Physical damage and additional Physical damage every second for $48130d."},
			{id=7678,title="Stomp",body="The Ferocious Rhino stomps the ground, inflicting Physical damage to all players within $48131A1 yards, stunning them for $48131d."},
			{id=7672,title="Frenzied Worgen"},
			{id=7679,title="Mortal Wound",body="The Frenzied Worgen mortally wounds a player, inflicting Physical damage and reducing the effectiveness of all healing received by $48137s2% for $48137d. This effect stacks up to $48137U times."},
			{id=7680,title="Enrage",body="The Frenzied Worgen enrages, increasing its attack speed by $48138s1% for $48138d."},
			{id=7673,title="Massive Jormungar"},
			{id=7681,title="Acid Spit",body="The Massive Jormungar spits a ball of acid at a player, inflicting Nature damage and reducing their armor by $48132s2 for $48132d. This effect stacks up to $48132U times."},
			{id=7682,title="Poison Breath",body="The Massive Jormungar breathes poison on all players in front of it, inflicting Nature damage and additional Nature damage every $48133t3 sec., for $48133d."},
			{id=7683,title="Acid Splatter",body="The Massive Jormungar summons Jormungar Worms that attack players."},
			{id=7684,title="Jormungar Worm",body="Jormungar Worms defend the Massive Jormungar."},
			{id=7674,title="Ravenous Furbolg"},
			{id=7685,title="Crazed",body="The Ravenous Furbolg goes into a craze, increasing its movement speed by $48139s3% and attacking players at random for $48139d."},
			{id=7686,title="Terrifying Roar",body="The Ravenous Furbolg unleashes a terrifying roar, causing all players within $48144A1 yards to flee in terror for $48144d."},
			{id=7687,title="Chain Lightning",body="The Ravenous Furbolg strikes a player with a bolt of lightning that arcs to another nearby player, inflicting Nature damage to each of them. Chain Lightning can affect up to $48140x1 targets."},
			{id=7675,title="Stage 2: Gortok Palehoof"},
			{id=7688,title="Withering Roar",body="Gortok Palehoof unleashes a roar, inflicting Physical damage to all players and lowering their maximum health. This effect lasts for $48256d., and stacks up to $48256U times."},
			{id=7689,title="Arcing Smash",body="Gortok Palehoof lashes out in a vicious arc, inflicting Physical damage to all players in front of him."},
			{id=7690,title="Impale",body="Gortok Palehoof throws a spear at a random player, inflicting Physical damage and additional Physical damage every $48261t2 sec., for $48261d."},
		},
	},
	[643]={
		encounterID=643,
		instanceID=286,
		order=3,
		name="Skadi the Ruthless",
		lore="The vrykul assign nicknames based on accomplishments. Cleansing a Drakkari bloodline or decapitating taunka might garner the appellation of \"dutiful,\" but it takes a true act of depravity to be called \"ruthless.\" Skadi earned his title long ago for relentlessly hunting down vrykul who sheltered the malformed infants, predecessors of humanity, condemned by Ymiron.",
		dungeonEncounterID=2029,
		uiMapID=137,
		pin={x=0.6844,y=0.3627},
