		},
		sections={
			{id=7691,title="Stage 1: Grauf",body="Skadi the Ruthless starts the fight by mounting his drake, Grauf. While mounted, Skadi will fly overhead and order Grauf to breathe freezing clouds onto players below.\n\nSkadi remains mounted until players fire three harpoons at Grauf by using the Harpoon Launcher."},
			{id=7692,title="Freezing Cloud",body="Grauf breathes a freezing cloud onto the ground, inflicting Frost damage to all players within it. The cloud persists on the ground for $47579d."},
			{id=7693,title="Harpoon Launcher",body="Players who possess a harpoon can use the Harpoon Launchers found near Grauf to inflict Physical damage to him when he is within range of the launcher.\n\nHarpoons are obtained by killing Ymirjar Harpooners."},
			{id=7694,title="Ymirjar Harpooner"},
			{id=7695,title="Throw",body="Ymirjar Harpooners throw their weapon at a player, inflicting Physical damage."},
			{id=7696,title="Net",body="Ymirjar Harpooners throw a net at a player, rooting them in place for $49092d."},
			{id=7697,title="Drop Harpoon",body="When Ymirjar Harpooners die, they drop a Harpoon on the ground that players can pick up and use with the Harpoon Launcher."},
			{id=7698,title="Ymirjar Warrior"},
			{id=7699,title="Hamstring",body="Ymirjar Warriors inflict Physical damage to a player, reducing their movement speed by $48639s2% for $48639d."},
			{id=7700,title="Strike",body="Ymirjar Warriors strike a player, inflicting Physical damage."},
			{id=7701,title="Ymirjar Witch Doctor"},
			{id=7702,title="Shadow Bolt",body="Ymirjar Witch Doctors hurl a bolt of dark magic at a player, inflicting Shadow damage."},
			{id=7703,title="Shrink",body="Ymirjar Witch Doctors shrink a player, reducing their strength and stamina by $49089s1 for $49089d."},
			{id=7704,title="Stage 2: Skadi the Ruthless"},
			{id=7705,title="Whirlwind",body="Skadi the Ruthless attacks all players within $50229A1 yards in a whirlwind of steel that lasts $50228d., inflicting Physical damage each time he spins. While whirlwinding, Skadi the Ruthless' movement speed is reduced by $50228s2%."},
			{id=7706,title="Crush",body="Skadi the Ruthless crushes a player, inflicting Physical damage and stunning them for $50234d."},
			{id=7707,title="Poisoned Spear",body="Skadi the Ruthless throws a poisoned spear at a random player, inflicting Physical damage and additional Nature damage every $50258t1 sec., for $50258d."},
		},
	},
	[644]={
