		sections={
			{id=7708,title="Gift of the Fallen Kings",body="When King Ymiron reaches 66% and 33% health remaining, he calls upon a fallen vrykul king to grant him a new ability. He retains this ability until he chooses a new fallen king.$[!2\n\nIn Heroic Difficulty, King Ymiron calls on a fallen king at 80%, 60%, 40% and 20% health remaining.$]"},
			{id=7711,title="Spirit Burst",body="Ranulf of the Screaming Abyss grants King Ymiron the ability to unleash a burst of spirit energy, inflicting Shadow damage to all players."},
			{id=7713,title="Summon Spirit Fount",body="Bjorn of the Black Storm grants King Ymiron the ability to summon a spirit fount that inflicts Shadow damage to a random player every second."},
			{id=7715,title="Spirit Strike",body="Haldor of the Rocky Cliffs grants King Ymiron the ability to strike a player, inflicting Physical damage and increasing their Physical damage taken for $48423d. This effect stacks up to $48423U times."},
			{id=7717,title="Summon Avenging Spirits",body="Tor of the Brutal Siege grants King Ymiron the ability to summon 4 Avenging Spirits to attack players."},
			{id=7721,title="Avenging Spirit"},
			{id=7722,title="Wither",body="Avenging Spirit's melee attacks reduce all stats by $48585s1% for $48585d. This effect stacks up to $48585U times."},
			{id=7709,title="Screams of the Dead",body="Whenever King Ymiron chooses a fallen king, he unleashes a bone chilling scream that stuns all players for $51750d."},
			{id=7718,title="Bane",body="King Ymiron is surrounded with an aura of Bane, which inflicts Shadow damage to all players within $48295A1 yards whenever he takes direct damage. This effect lasts for $48294d."},
			{id=7719,title="Dark Slash",body="King Ymiron slashes a player, inflicting damage equal to half of their current health."},
			{id=7720,title="Fetid Rot",body="King Ymiron afflicts a player with Fetid Rot, inflicting Nature damage every $48291t1 sec. and decreasing healing received by $48291s2% for $48291d."},
		},
