	[834]={
		encounterID=834,
		instanceID=284,
		order=2,
		name="Grand Champions",
		lore="The Lich King is relentless, his undead armies pouring forth to overwhelm his foes. To prepare would-be champions against him, Highlord Tirion Fordring presents a test of courage, endurance, and teamwork. His hardened veterans will weed out those who lack the stomach to face the ravening throngs of undead.",
		dungeonEncounterID=2022,
		uiMapID=171,
		pin={x=0.5123,y=0.5266},
		difficultyIDs={1,2},
		npcIDs={34657,34701,34702,34703,34705,35569,35570,35571,35572,35617},
		displayIDs={28560,28564,28586,28735,28736},
		loot={
			{itemID=47248,diffs={1,2},faction=-1},
			{itemID=47249,diffs={1,2},faction=-1},
			{itemID=47250,diffs={1,2},faction=-1},
