			{itemID=47493,diffs={1,2},faction=-1},
			{itemID=47173,diffs={1,2},faction=-1},
			{itemID=47174,diffs={1,2},faction=-1},
			{itemID=47175,diffs={1,2},faction=-1},
			{itemID=47243,diffs={1,2},faction=-1},
