			{itemID=47181,diffs={1,2},faction=-1},
		},
		sections={
			{id=7536,title="The Joust",body="Players face three randomly selected champions of the Alliance in a battle of joust. Each player must equip an Argent Lance and mount an Argent Battleworg to engage the champions."},
			{id=7537,title="Argent Battleworg"},
			{id=7538,title="Thrust",body="Players thrust their lance forward, inflicting Physical damage to their target."},
			{id=7539,title="Shield-Breaker",body="Players hurl their lance across the battlefield, inflicting Physical damage to their target and removing one stack of Defend from them."},
			{id=7540,title="Charge",body="Players charge forward, inflicting Physical damage and removing one stack of Defend from their target."},
			{id=7541,title="Defend",body="Players protect themselves, reducing damage taken by 30%. Enemy strikes from Shield-Breaker or Charge remove one stack of Defend. This effect stacks up to 3 times."},
			{id=7542,title="Trample",body="Players can trample champions that have been knocked from their mount by riding over them. Trampling an enemy stuns them for 15 seconds, preventing them from obtaining a new mount."},
			{id=7543,title="The Champions",body="The three randomly selected champions face players on their Argent Warhorses, using the same abilities as the Argent Battleworg."},
			{id=7544,title="The Melee",body="Once all of the champions have been defeated in joust, players must face them in melee."},
			{id=7545,title="Marshal Jacob Alerius"},
			{id=7546,title="Intercept",body="Marshal Jacob Alerius charges a player, inflicting Physical damage."},
			{id=7547,title="Bladestorm",body="Marshal Jacob Alerius attacks all players within $67716A1 yards, inflicting Physical damage every second for $67541d."},
			{id=7548,title="Mortal Strike",body="Marshal Jacob Alerius mortally wounds a player, inflicting Physical damage and reducing the effectiveness of any healing they receive by $67542s2% for $67542d."},
			{id=7549,title="Rolling Throw",body="Marshal Jacob Alerius throws a player backwards."},
			{id=7550,title="Ambrose Boltspark"},
			{id=7551,title="Fireball",body="Ambrose Boltspark hurls a ball of flames at a player, inflicting Fire damage."},
			{id=7552,title="Polymorph",body="Ambrose Boltspark transforms a player into a sheep, forcing them to wander aimlessly for $66043d., unable to act. Any damage taken will transform the target back into its normal form."},
			{id=7553,title="Blast Wave",body="Ambrose Boltspark unleashes a wave of flame, inflicting Fire damage to all players within $66044A1 yards and reducing their movement speed for $66044d."},
			{id=7554,title="Haste",body="Ambrose Boltspark increases the attack and casting speed of an ally by $66045s1% for $66045d."},
			{id=7555,title="Colosos"},
			{id=7556,title="Healing Wave",body="Colosos calls upon Nature magic to heal an ally."},
			{id=7557,title="Chain Lightning",body="Colosos strikes a player with lightning that arcs to another nearby player. The spell affects up to $67529x1 targets, inflicting greater Nature damage to each successive target."},
			{id=7558,title="Earth Shield",body="Colosos protects an ally with an earthen shield, causing melee attacks to heal the shielded target.  This effect can only occur once every few seconds.  Earth Shield has $67530n charges and lasts for $67530d."},
			{id=7559,title="Hex of Mending",body="Colosos places a hex on a player, causing all direct heals they receive to heal their enemies within $67535A1 yards."},
			{id=7560,title="Jaelyne Evensong"},
			{id=7561,title="Shoot",body="Jaelyne Evensong shoots a player, inflicting Physical damage."},
			{id=7562,title="Multi-Shot",body="Jaelyne Evensong fires a volley of missiles at a player and their nearby allies, striking up to $66081x1 targets, inflicting Physical damage."},
			{id=7563,title="Lightning Arrows",body="Jaelyne Evensong calls forth lightning which strikes his arrows, causing them to inflict additional Nature damage.  Lightning Arrows has $66085n charges and lasts for $66085d."},
			{id=7564,title="Disengage",body="Jaelyne Evensong attempts to disengage from players, leaping backwards."},
			{id=7565,title="Lana Stouthammer"},
			{id=7566,title="Deadly Poison",body="Lana Stouthammer coats her weapons in deadly poison, causing her melee attacks to inflict Nature damage and additional Nature damage every $67710t1 sec. for $67710d. This effect stacks up to $67710U times."},
			{id=7567,title="Fan of Knives",body="Lana Stouthammer throws a fan of knives, inflicting Physical damage to all players within $67706A1 yards."},
			{id=7568,title="Poison Bottle",body="Lana Stouthammer throws a bottle of poison at a random player's location. The poison persists on the ground for $67594d and inflicts Nature damage to anyone within $67594A1 yards."},
			{id=7569,title="Eviscerate",body="Lana Stouthammer eviscerates a player, inflicting Physical damage."},
		},
	},
