		sections={
			{id=17520,title="Overview",body="Thorim calls in Dark Rune forces to engage players that are in the Arena until allies are able to reach Thorim by traveling through the Hallway. Once players reach Thorim he will leap into the arena and use powerful Lightning attacks to defeat his foes."},
			{id=17521,title="Damage Dealers",body="$bullet;While in the Arena interrupt the Dark Rune Acolyte's |cFF2959D3|Hspell:62334|h[Greater Heal]|h|r and the |cFF2959D3|Hspell:62446|h[Runic Mending]|h|r cast by Dark Rune Evokers.\n$bullet;Avoid Thorim's |cFF2959D3|Hspell:62279|h[Lightning Charge]|h|r once Stage Two begins.\n$bullet;While in the Hallway avoid|cFF2959D3|Hspell:62465|h[Runic Smash]|h|r cast by the Runic Colossus."},
			{id=17522,title="Healers",body="$bullet;Avoid Thorim's |cFF2959D3|Hspell:62279|h[Lightning Charge]|h|r once Stage Two begins."},
			{id=17523,title="Tanks",body="$bullet;Avoid Thorim's |cFF2959D3|Hspell:62279|h[Lightning Charge]|h|r once Stage Two begins.\n$bullet;While in the Hallway avoid|cFF2959D3|Hspell:62465|h[Runic Smash]|h|r cast by the Runic Colossus.\n$bullet;While in the Hallway avoid|cFF2959D3|Hspell:62339|h[Smash]|h|r cast by the Runic Colossus once it is engaged.\n$bullet;Take turns tanking Thorim to manage |cFF2959D3|Hspell:62130|h[Unbalancing Strike]|h|r."},
			{id=17524,title="Stage One: Prove Your Worth",body="Thorim calls in Dark Rune forces to engage players that are in the Arena until allies are able to reach Thorim by traveling through the Hallway."},
