		sections={
			{id=17579,title="Overview",body="Mimiron engages his enemies with inventions rather than directly in combat. The Leviathan MK II is a deadly vehicle that assaults the Tank with powerful attacks, the VX-001 which strikes enemies with rocket blasts and laser barrages, the Aerial Command Unit which engages enemies from the skies, and finally the V0-L7R-0N unit, which combines the might of all of his inventions."},
			{id=17580,title="Damage Dealers",body="$bullet;Avoid the Leviathan Mk II's |cFF2959D3|Hspell:63016|h[Proximity Mines]|h|r when fleeing from |cFF2959D3|Hspell:63631|h[Shock Blast]|h|r.\n$bullet;Be spread apart to avoid the Leviathan Mk II's |cFF2959D3|Hspell:63666|h[Napalm Shell]|h|r.\n$bullet;Rotate away from VX-001's |cFF2959D3|Hspell:63293|h[P3Wx2 Laser Barrage]|h|r ability.\n$bullet;Use the Magnetic Core dropped by the Assault Bot to ground the Aerial Command Unit."},
			{id=17581,title="Healers",body="$bullet;Be spread apart to avoid the Leviathan Mk II's |cFF2959D3|Hspell:63666|h[Napalm Shell]|h|r.\n$bullet;Prepare for heavy damage on the Tank when the Leviathan Mk II casts |cFF2959D3|Hspell:62997|h[Plasma Blast]|h|r.\n$bullet;Rotate away from VX-001's |cFF2959D3|Hspell:63293|h[P3Wx2 Laser Barrage]|h|r ability."},
			{id=17582,title="Tanks",body="$bullet;Prepare for heavy damage when the Leviathan Mk II casts |cFF2959D3|Hspell:62997|h[Plasma Blast]|h|r.\n$bullet;Rotate away from VX-001's |cFF2959D3|Hspell:63293|h[P3Wx2 Laser Barrage]|h|r ability.\n$bullet;Use the Magnetic Core dropped by the Assault Bot to ground the Aerial Command Unit."},
