			{id=17680,title="Thorim"},
			{id=17681,title="Section 33"},
			{id=17682,title="Section 34"},
			{id=17658,title="Stage One: The Lucid Dream",body="As Sara assaults her enemies Guardians of Yogg-Saron will periodically join the battle."},
			{id=17659,title="Sara"},
			{id=17660,title="Section 7"},
			{id=17661,title="Section 8"},
			{id=17662,title="Section 9"},
			{id=17663,title="Guardian of Yogg-Saron",body="Casts |cFF2959D3|Hspell:62714|h[Shadow Nova]|h|r when defeated."},
			{id=17664,title="Section 11"},
			{id=17668,title="Ominous Cloud",body="Ominous Clouds slowly move through the Prison of Yogg-Saron and will |cFF2959D3|Hspell:63030|h[Boil Ominously]|h|r if an enemy strays too close."},
			{id=17669,title="Section 16"},
			{id=17666,title="Stage Two: Descent Into Madness",body="Yogg-Saron reveals himself and begins his assault on his enemies mind."},
			{id=17667,title="Section 14"},
			{id=17683,title="Sara"},
			{id=17684,title="Section 20"},
			{id=17685,title="Section 19"},
			{id=17686,title="Section 20"},
