			{id=17699,title="Section 46"},
			{id=17696,title="Descent into Madness",body="When entering the Descent into Madness you will witness memories of the past. Defeating all Influence Tentacles will break the illusion and allow access to the Mind's Eye, where the Brain of Yogg-Saron resides."},
			{id=17701,title="Influence Tentacle",body="Able to take many forms."},
			{id=17702,title="Section 49"},
			{id=17703,title="Laughing Skull"},
			{id=17704,title="Section 51"},
			{id=17705,title="Brain of Yogg-Saron"},
			{id=17706,title="Section 53"},
			{id=17707,title="Stage Three: True Face of Death",body="When the Brain of Yogg-Saron reaches 30% health remaining, Yogg Saron's |cFF2959D3|Hspell:63894|h[Shadowy Barrier]|h|r will fall and he can be assaulted directly."},
