			{id=17711,title="Section 56"},
			{id=17712,title="Section 57"},
			{id=17713,title="Immortal Guardian",body="Immortal Guardians can only be killed by Thorim's |cFF2959D3|Hspell:64171|h[Titanic Storm]|h|r."},
			{id=17714,title="Section 59"},
			{id=17715,title="Hard Mode",body="Battling Yogg-Saron without the aid of some or all of the Keepers of Ulduar for assistance is possible, but extremely dangerous."},
